type ButtonProps = {
  className?: string;
  variant?: "primary" | "secondary";
};

export default function Button({ className, variant = "primary" }: ButtonProps) {
  const isSecondary = variant === "secondary";
  return (
    <div className={className || `${String.raw`content-stretch flex gap-[var(--space\/sm,8px)] items-center justify-center px-[var(--space\/md,16px)] py-[var(--space\/sm,8px)] relative `}${isSecondary ? String.raw`bg-[var(--color\/button\/secondary\/bg,#e2e8f0)]` : String.raw`bg-[var(--color\/button\/primary\/bg,#2563eb)]`}`} id={isSecondary ? "node-1_14" : "node-1_12"}>
      <p className={`[word-break:break-word] font-["Inter:Semi_Bold"] font-semibold leading-[20px] not-italic relative shrink-0 text-[14px] whitespace-nowrap ${isSecondary ? String.raw`text-[color:var(--color\/button\/secondary\/fg,#1e293b)]` : String.raw`text-[color:var(--color\/button\/primary\/fg,white)]`}`} id={isSecondary ? "node-1_15" : "node-1_10"} data-annotations={variant === "primary" ? "\\[a11y\\] 라벨을 시각적으로 숨기지 않는다" : undefined}>
        Button
      </p>
    </div>
  );
}
